//! The AWP 2.0 test vectors regenerate byte-identically, match the committed copies in
//! `tests/fixtures/vectors/`, and each case evaluates to its expected outcome (spec 3.5 §7.7,
//! §11).
//!
//! A drifted vector fails the test on every run, retries included: the regenerated bytes are
//! written under the target directory for review, never over the committed copies. After a
//! deliberate change, rewrite the committed copies, then copy the directory into the protocol
//! repository's `vectors/`:
//!
//! ```bash
//! AWP_UPDATE_VECTORS=1 cargo nextest run -p adk-awp --features verify --test v2_vectors
//! ```

#![cfg(feature = "verify")]

use std::path::{Path, PathBuf};

use adk_awp::conformance::vectors::{case_bytes, check_case, generate};
use serde_json::Value;

/// Set to `1` to rewrite the committed vectors from this build.
const UPDATE: &str = "AWP_UPDATE_VECTORS";

/// Where a drifted vector's regenerated bytes go for review.
fn review_dir() -> PathBuf {
    std::env::var_os("CARGO_TARGET_TMPDIR")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir)
        .join("awp-vectors")
}

#[tokio::test]
async fn vectors_are_deterministic_and_committed() {
    let first = generate().await.unwrap();
    let second = generate().await.unwrap();
    assert_eq!(
        first.iter().map(|(n, c)| (n.clone(), case_bytes(c))).collect::<Vec<_>>(),
        second.iter().map(|(n, c)| (n.clone(), case_bytes(c))).collect::<Vec<_>>(),
        "two runs produce the same bytes"
    );

    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/vectors");
    let update = std::env::var(UPDATE).is_ok_and(|value| value == "1");
    let target = if update { dir.clone() } else { review_dir() };
    let mut drifted = Vec::new();
    for (name, case) in &first {
        let bytes = case_bytes(case);
        if std::fs::read(dir.join(name)).ok().as_deref() != Some(bytes.as_slice()) {
            let path = target.join(name);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(&path, &bytes).unwrap();
            drifted.push(name.clone());
        }
    }
    let committed: Vec<String> = walk(&dir)
        .into_iter()
        .filter_map(|path| {
            let name = path.strip_prefix(&dir).ok()?.to_string_lossy().replace('\\', "/");
            (!first.contains_key(&name)).then_some(name)
        })
        .collect();
    assert!(committed.is_empty(), "committed vectors no case generates: {committed:#?}");
    if update {
        return;
    }
    assert!(
        drifted.is_empty(),
        "vectors drifted; the regenerated bytes are under {}. Review them, then run with \
         {UPDATE}=1 and commit: {drifted:#?}",
        target.display()
    );
}

/// Every file under `dir`.
fn walk(dir: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for entry in std::fs::read_dir(dir).into_iter().flatten().flatten() {
        let path = entry.path();
        if path.is_dir() {
            files.extend(walk(&path));
        } else {
            files.push(path);
        }
    }
    files
}

#[tokio::test]
async fn every_case_evaluates_to_its_expectation() {
    let cases = generate().await.unwrap();
    assert!(cases.len() >= 18);
    for (name, case) in &cases {
        let vector = name.split('/').next().unwrap();
        let outcome = check_case(vector, case).unwrap_or_else(|e| panic!("{name}: {e}"));
        let expected = &case["expected"];
        if expected["valid"] == Value::Bool(true) {
            assert_eq!(outcome, None, "{name}");
        } else {
            assert_eq!(outcome, expected["failure"].as_str(), "{name}");
        }
    }
}
